Let me recall the actual upstream fix. Upstream commit: "Fix attaching postgres table with datetime" — PR #42100? The actual code in current master:

```cpp
ASTPtr DatabasePostgreSQL::getColumnDeclaration(const DataTypePtr & data_type) const
{
    WhichDataType which(data_type);

    if (which.isNullable())
        return makeASTFunction("Nullable", getColumnDeclaration(typeid_cast<const DataTypeNullable *>(data_type.get())->getNestedType()));

    if (which.isArray())
        return makeASTFunction("Array", getColumnDeclaration(typeid_cast<const DataTypeArray *>(data_type.get())->getNestedType()));

    if (which.isDateTime64())
    {
        auto ast_expression = std::make_shared<ASTFunction>();
        ast_expression->name = "DateTime64";
        ast_expression->arguments = std::make_shared<ASTExpressionList>();
        ast_expression->children.push_back(ast_expression->arguments);

        const auto * datetime64 = typeid_cast<const DataTypeDateTime64 *>(data_type.get());
        ast_expression->arguments->children.emplace_back(std::make_shared<ASTLiteral>(datetime64->getScale()));

        if (datetime64->hasExplicitTimeZone())
            ast_expression->arguments->children.emplace_back(std::make_shared<ASTLiteral>(datetime64->getTimeZone().getTimeZone()));

        return ast_expression;
    }

    return std::make_shared<ASTIdentifier>(data_type->getName());
}
